#include <stdio.h>

#define MAX(a, b) ((a) > (b) ? (a) : (b))

#define MAX_SIZE 1001

int main() {
    // 一个正整数数组表示待系统执行的任务列表
    int tasks[MAX_SIZE];
    int tasks_size = 0;

    while (scanf("%d", &tasks[tasks_size++])) {
        if (getchar() != ',') break;
    }

    // 任务冷却时间
    int n;
    scanf("%d", &n);

    // k表示:最多任务的数量
    // 比如2,2,2,3， 其中任务2数量最多，有3个，则k = 3
    int k = 0;

    int cnts[MAX_SIZE] = {0};
    for (int i = 0; i < tasks_size; i++) {
        int task = tasks[i];
        cnts[task]++;
        k = MAX(k, cnts[task]);
    }

    // p表示:数量为k的任务个数
    // 比如2,2,2,3,3,3,4， 其中数量为3的任务有2个，分别是任务2，任务3，则p=2
    int p = 0;
    for (int i = 0; i < MAX_SIZE; i++) {
        if (cnts[i] == k) p++;
    }

    printf("%d\n", MAX((k - 1) * (n + 1) + p, tasks_size));

    return 0;
}
